+# v1 -> v2 migration UI rehearsal for Playwright (#992) — layers onto
+# docker-compose.e2e.yml so `backend/scripts/seed_e2e_migration_fixture.py`
+# (run from the host) can seed a legacy-shaped fixture straight into Postgres
+# before the stack's own backend starts and runs the real startup migration
+# against it. Mirrors docker-compose.rehearsal.yml's approach for the same
+# reason: the seed script isn't part of the built backend image, so it has to
+# run against a host-reachable database.
+#
+#   docker compose -f docker-compose.e2e.yml -f docker-compose.e2e.migrated.yml up -d db redis
+#   cd backend && uv run python -m scripts.seed_e2e_migration_fixture \
+#       --database-url REDACTED
+#   docker compose -f docker-compose.e2e.yml -f docker-compose.e2e.migrated.yml up --build -d
+#   cd e2e && npx playwright test --config=playwright.migrated.config.ts
+#
+# All credentials and ports here are throwaway values, safe for CI only.
+
+services:
+  db:
+    ports:
+      - "5434:5432"
+
+  backend:
+    environment:
+      # The migration preflight refuses to run with a short/placeholder
+      # SECRET_KEY (it would encrypt the automatic pre-migration backup with
+      # no real protection) — a check the plain fresh-install e2e stack never
+      # exercises, since a fresh install has nothing to convert.
+      SECRET_KEY: REDACTED
