 /**
  * Low-level API helper for E2E tests.
  * All calls go through the backend REST API so tests can arrange state without
  * driving the UI.  Pass a JWT token obtained from apiLogin().
  */

 import { API_URL } from "../playwright.config";

+// The backend's SchemaEpochMiddleware (#1012) fails closed any mutation that
+// doesn't declare the wire contract it was written against — mirrors
+// frontend/src/services/api.ts's FRONTEND_SCHEMA_EPOCH. Bump both together.
+export const SCHEMA_EPOCH_HEADER = "X-Schema-Epoch";
+export const CURRENT_SCHEMA_EPOCH = "2";
+
 export interface ApiClient {
   token: string;
   get<T = unknown>(path: string): Promise<T>;
   post<T = unknown>(path: string, body?: unknown): Promise<T>;
   patch<T = unknown>(path: string, body: unknown): Promise<T>;
   delete(path: string): Promise<void>;
 }

 export async function apiLogin(
   username: string,
   password: string,
 ): Promise<string> {
   const res = await fetch(`${API_URL}/auth/login`, {
     method: "POST",
     headers: { "Content-Type": "application/json" },
     body: JSON.stringify({ username, password }),
   });
   if (!res.ok) {
     const text = await res.text();
     throw new Error(`Login failed ${res.status}: ${text}`);
   }
   const data = (await res.json()) as { access_token?: string };
   if (!data.access_token) throw new Error("Login returned no access_token");
   return data.access_token;
 }

 export async function waitForJob(
   token: string,
   jobId: string,
   maxAttempts = 30,
   intervalMs = 1000,
 ): Promise<string> {
   for (let attempt = 0; attempt < maxAttempts; attempt++) {
     const res = await fetch(`${API_URL}/jobs/${jobId}`, {
       headers: { Authorization: `Bearer ${token}` },
     });
     if (!res.ok) throw new Error(`GET /jobs/${jobId} → ${res.status}`);
     const job = (await res.json()) as {
       status: string;
       result_workspace_id?: string;
       error?: string;
     };
-    if (job.status === "done" && job.result_workspace_id) return job.result_workspace_id;
+    if (job.status === "done" && job.result_workspace_id)
+      return job.result_workspace_id;
     if (job.status === "failed") throw new Error(`Job failed: ${job.error}`);
     await new Promise((resolve) => setTimeout(resolve, intervalMs));
   }
   throw new Error(
     `Job ${jobId} did not complete after ${maxAttempts} attempts`,
   );
 }

 export function makeApiClient(token: string): ApiClient {
   const headers = () => ({
     "Content-Type": "application/json",
     Authorization: `Bearer ${token}`,
+    [SCHEMA_EPOCH_HEADER]: CURRENT_SCHEMA_EPOCH,
   });

   async function request<T>(
     method: string,
     path: string,
     body?: unknown,
   ): Promise<T> {
     const url = path.startsWith("http") ? path : `${API_URL}${path}`;
     const res = await fetch(url, {
       method,
       headers: headers(),
       body: body !== undefined ? JSON.stringify(body) : undefined,
     });
     if (!res.ok) {
       const text = await res.text();
       throw new Error(`${method} ${path} → ${res.status}: ${text}`);
     }
     if (res.status === 204) return undefined as T;
     return res.json() as Promise<T>;
   }

   return {
     token,
     get: <T>(path: string) => request<T>("GET", path),
     post: <T>(path: string, body?: unknown) => request<T>("POST", path, body),
     patch: <T>(path: string, body: unknown) => request<T>("PATCH", path, body),
     delete: (path: string) => request<void>("DELETE", path),
   };
 }
